-- Migration 57: Alto Penalolen (Varelectric) — edificio + 55 medidores
--
-- Origen: docs/Dump20260728_altopena.sql, DB MySQL `altopena2`, tabla
-- `configuracion` (65 filas). Se excluyen 10 remarcadores cuyo voltaje cae
-- fuera de todo rango fisico (0V o >20% de lecturas fuera de 180-260 / 340-440):
--   114, 115, 217, 219, 232, 236, 237, 246, 105, 214
--
-- El dump no registra potencia antes de 2025 (tag9=0 en el 100% de esas filas)
-- pero si el contador de energia, asi que la potencia de 2022-2024 se deriva
-- del delta de energia. La columna power_kw_derived marca cuales son calculadas.

ALTER TABLE readings ADD COLUMN IF NOT EXISTS power_kw_derived boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN readings.power_kw_derived IS
  'true = power_kw calculado desde el delta de energy_kwh_total, no medido';

